"""Signal, border, emergency, and queue facts for the offline bank."""

from __future__ import annotations


def pack(track: str, rows: list[tuple[str, str, str]]) -> list[dict]:
    return [{"track": track, "term": term, "def": definition, "why": why} for term, definition, why in rows]


